Definition bidx (SB b : Z) : nat := Z.to_nat ((b - SB - 24 * 2 ^ 32) / 8192).
Definition bslots (SB : Z) (bs : list batch) : list (Z * nat) := map (fun b => (24, bidx SB (fst b))) bs.

